code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append((color, cells))

    def has_hole(cells):
        minr=min(r for r,c in cells); maxr=max(r for r,c in cells)
        minc=min(c for r,c in cells); maxc=max(c for r,c in cells)
        occupied=set(cells)
        outside=set()
        q=deque()
        for r in range(minr,maxr+1):
            for c in range(minc,maxc+1):
                if (r,c) not in occupied and (r in (minr,maxr) or c in (minc,maxc)):
                    outside.add((r,c)); q.append((r,c))
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if minr <= p[0] <= maxr and minc <= p[1] <= maxc and p not in occupied and p not in outside:
                    outside.add(p); q.append(p)
        return any((r,c) not in occupied and (r,c) not in outside
                   for r in range(minr,maxr+1) for c in range(minc,maxc+1))

    placed=[]
    for upward in (True, False):
        group=[(color,cells) for color,cells in comps if has_hole(cells)==upward]
        group.sort(key=lambda item: min(r for r,c in item[1]), reverse=not upward)
        for color,cells in group:
            row0=min(r for r,c in cells)
            positions={(r-row0,c) for r,c in cells}
            offset=row0
            step=-1 if upward else 1
            while True:
                nxt=offset+step
                if any(not (0 <= nxt+dr < h and 0 <= c < w) for dr,c in positions):
                    break
                if any((nxt+dr,c) in occ for dr,c in positions for occ in placed):
                    break
                offset=nxt
            placed.append({(offset+dr,c) for dr,c in positions})
            # Store color alongside the translated cells for rendering.
            placed[-1]=(color, placed[-1])
    out=[[0]*w for _ in range(h)]
    for color, cells in placed:
        for r,c in cells:
            out[r][c]=color
    return out
'''
